            &&& (network().init)(s.network)
            // and message drop is enabled...
            &&& s.req_drop_enabled
            // and pod monkey is enabled...
            &&& s.pod_monkey_enabled
            // and for each controller...
            &&& forall |key| #[trigger] self.controller_models.contains_key(key)
